package net.officefloor.hq.app.search;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** Search the people of a sheet's tree by name or alias. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/search")
public class TreeSearchController {

    /** A person found: their sheet id, name, grade in force on their sheet's today and due-total (two decimals; n/a when they have none). */
    public record FoundView(String sheetId, String name, String grade, String dueTotal) {
    }

    private final TreeSearchService service;

    public TreeSearchController(TreeSearchService service) {
        this.service = service;
    }

    /** The people whose name or an alias contains the text, case ignored. */
    @GetMapping
    public List<FoundView> search(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestParam(defaultValue = "") @Size(max = 200) String text) {
        return service.search(sheetId.trim(), text).stream()
                .map(f -> new FoundView(f.sheetId(), f.name(), f.grade(),
                        f.dueTotal() == null ? "n/a" : f.dueTotal().toPlainString()))
                .toList();
    }
}
package net.officefloor.hq.app.search;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Finds people over a sheet and every other sheet of its tree (its ancestors and their descendants) by
 * a piece of their name or an alias, case ignored. It reads; it records nothing.
 */
@Service
public class TreeSearchService {

    /** A person found: their sheet, their name, their grade in force on their sheet's today and their due-total as their sheet shows it (null for n/a). */
    public record Found(String sheetId, String name, String grade, BigDecimal dueTotal) {
    }

    private final PersonRepository people;
    private final SheetRepository sheets;
    private final Rollup rollup;

    public TreeSearchService(PersonRepository people, SheetRepository sheets, Rollup rollup) {
        this.people = people;
        this.sheets = sheets;
        this.rollup = rollup;
    }

    /** Everyone whose name or an alias contains the text (blank matches everyone): the sheet's own people
     *  first in list order, then the other sheets' of its tree, by sheet id, each in list order. */
    @Transactional(readOnly = true)
    public List<Found> search(String sheetId, String text) {
        String key = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
        List<Found> found = new ArrayList<>();
        List<String> order = new ArrayList<>(List.of(sheetId));
        sheets.tree(sheetId).stream().filter(s -> !s.equals(sheetId)).sorted().forEach(order::add);
        for (String sheet : order) {
            Rollup.Snapshot snapshot = rollup.take(sheet);
            LocalDate today = sheets.findById(sheet).map(Sheet::getToday).orElseThrow();
            for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheet)) {
                if (matches(person, key)) {
                    Rollup.Figures figures = snapshot.people().get(person.getId());
                    found.add(new Found(sheet, person.getName(), person.gradeOn(today), figures == null ? null : figures.dueTotal()));
                }
            }
        }
        return found;
    }

    private static boolean matches(Person person, String key) {
        if (person.getName().toLowerCase(Locale.ROOT).contains(key)) {
            return true;
        }
        return person.getAliases().stream().anyMatch(a -> a.toLowerCase(Locale.ROOT).contains(key));
    }
}
